struct SingleRows
    : protected ioj::native_soa::StorageState
    , ioj::native_soa::StorageOperations {
    using soa_schema = SingleRowsSchema;
    using Operations = ioj::native_soa::StorageOperations;
    using Layout = SingleRowsLayout;
    using size_type = Layout::size_type;
    using byte_size_type = Layout::byte_size_type;

    static constexpr auto capacity_granularity = Layout::capacity_granularity;
    static constexpr auto allocation_alignment = Layout::allocation_alignment;
    static constexpr auto capacity_block_bound = Layout::capacity_block_bound;
    static constexpr auto max_capacity = Layout::max_capacity;

    static constexpr auto layout_bytes(byte_size_type blocks) noexcept -> byte_size_type {
        return Layout::layout_bytes(blocks);
    }

    using View = SingleRowsView;
    using ConstView = SingleRowsConstView;

    /* **************************************** */
    // Lifetime
    /* **************************************** */
    SingleRows() noexcept
        : SingleRows{*std::pmr::get_default_resource()} {}
    explicit SingleRows(std::pmr::memory_resource& resource) noexcept
        : resource_{&resource} {}
    auto get_memory_resource() const noexcept -> std::pmr::memory_resource* { return resource_; }
    ~SingleRows() { Operations::release_storage(*this); }
    SingleRows(SingleRows const&) = delete;
    auto operator=(SingleRows const&) -> SingleRows& = delete;
    SingleRows(SingleRows&& other) noexcept
        : resource_{other.resource_} {
        Operations::take_storage(*this, other);
    }
    auto operator=(SingleRows&& other) -> SingleRows& {
        return Operations::move_assign(*this, other);
    }
  protected:
    template <typename Byte>
    struct DataPointers {
        template <typename T>
        using Element = std::conditional_t<std::is_const_v<Byte>, T const, T>;
        Element<std::int32_t>* values{};
        Element<float>* positions_xs{};
        Element<float>* positions_ys{};
        Element<float>* positions_zs{};
        Element<float>* velocities_xs{};
        Element<float>* velocities_ys{};
        Element<float>* velocities_zs{};
        auto operator+(size_type const offset) const noexcept -> DataPointers {
            if (values == nullptr) {
                return {};
            }
            return {values + offset,
                    positions_xs + offset,
                    positions_ys + offset,
                    positions_zs + offset,
                    velocities_xs + offset,
                    velocities_ys + offset,
                    velocities_zs + offset};
        }
    };
  private:
    friend Operations;
    friend ::ioj::soa_storage_detail::StorageRequirements;
    /* **************************************** */
    // Column pointers
    /* **************************************** */
    template <typename Byte>
    static auto make_data_unchecked(Byte* const data, byte_size_type const blocks) noexcept
        -> DataPointers<Byte> {
        ioj::native_soa::LayoutCursor cursor{blocks};
        return {cursor.column_pointer(data, Layout::columns.ValuesColumn),
                cursor.column_pointer(data, Layout::columns.Positions.XsColumn),
                cursor.column_pointer(data, Layout::columns.Positions.YsColumn),
                cursor.column_pointer(data, Layout::columns.Positions.ZsColumn),
                cursor.column_pointer(data, Layout::columns.Velocities.XsColumn),
                cursor.column_pointer(data, Layout::columns.Velocities.YsColumn),
                cursor.column_pointer(data, Layout::columns.Velocities.ZsColumn)};
    }

    /* **************************************** */
    // Typed mutations and growth
    /* **************************************** */
    void default_construct_columns(size_type const first, size_type const count) {
        using ioj::native_soa::default_construct_n;
        auto const columns{make_data_unchecked(data_, capacity_blocks()) + first};
        default_construct_n(columns.values, count);
        default_construct_n(columns.positions_xs, count);
        default_construct_n(columns.positions_ys, count);
        default_construct_n(columns.positions_zs, count);
        default_construct_n(columns.velocities_xs, count);
        default_construct_n(columns.velocities_ys, count);
        default_construct_n(columns.velocities_zs, count);
    }
    template <bool Overlapping, typename Byte>
    static void transfer_columns(DataPointers<std::byte> const& destination,
                                 DataPointers<Byte> const& source,
                                 size_type count) {
        auto transfer = [count](auto* dst, auto const* src) {
            ioj::native_soa::transfer_n<Overlapping>(dst, src, count);
        };
        transfer(destination.values, source.values);
        transfer(destination.positions_xs, source.positions_xs);
        transfer(destination.positions_ys, source.positions_ys);
        transfer(destination.positions_zs, source.positions_zs);
        transfer(destination.velocities_xs, source.velocities_xs);
        transfer(destination.velocities_ys, source.velocities_ys);
        transfer(destination.velocities_zs, source.velocities_zs);
    }
    template <typename Columns>
    static auto source_pointers(Columns const& source) -> DataPointers<std::byte const>
        requires ioj::soa_storage_detail::SoaSourceFor<Columns, SingleRows, size_type>
    {
        using ioj::native_soa::source_data;
        auto const& positions_view{source.view_positions()};
        auto const& velocities_view{source.view_velocities()};
        return {source_data(source.values()),
                source_data(positions_view.xs()),
                source_data(positions_view.ys()),
                source_data(positions_view.zs()),
                source_data(velocities_view.xs()),
                source_data(velocities_view.ys()),
                source_data(velocities_view.zs())};
    }
  public:
    auto values(this auto& self) { return self.get_view().values(); }
    auto view_positions(this auto& self) { return self.get_view().view_positions(); }
    auto view_velocities(this auto& self) { return self.get_view().view_velocities(); }
    void set(size_type index,
             std::int32_t const new_values,
             float const new_positions_xs,
             float const new_positions_ys,
             float const new_positions_zs,
             float const new_velocities_xs,
             float const new_velocities_ys,
             float const new_velocities_zs) {
        assert(index < num());
        get_view().values()[index] = new_values;
        get_view().view_positions().xs()[index] = new_positions_xs;
        get_view().view_positions().ys()[index] = new_positions_ys;
        get_view().view_positions().zs()[index] = new_positions_zs;
        get_view().view_velocities().xs()[index] = new_velocities_xs;
        get_view().view_velocities().ys()[index] = new_velocities_ys;
        get_view().view_velocities().zs()[index] = new_velocities_zs;
    }
    size_type add(std::int32_t const new_values,
                  float const new_positions_xs,
                  float const new_positions_ys,
                  float const new_positions_zs,
                  float const new_velocities_xs,
                  float const new_velocities_ys,
                  float const new_velocities_zs) {
        auto const index{num()};
        add_uninitialised(1);
        set(index,
            new_values,
            new_positions_xs,
            new_positions_ys,
            new_positions_zs,
            new_velocities_xs,
            new_velocities_ys,
            new_velocities_zs);
        return index;
    }
    void apply_permutation(std::span<size_type> indices) {
        assert(indices.size() == num_);
        auto const columns{get_data()};
        ioj::apply_permutation(std::span{columns.values, num_}, indices);
        ioj::apply_permutation(std::span{columns.positions_xs, num_}, indices);
        ioj::apply_permutation(std::span{columns.positions_ys, num_}, indices);
        ioj::apply_permutation(std::span{columns.positions_zs, num_}, indices);
        ioj::apply_permutation(std::span{columns.velocities_xs, num_}, indices);
        ioj::apply_permutation(std::span{columns.velocities_ys, num_}, indices);
        ioj::apply_permutation(std::span{columns.velocities_zs, num_}, indices);
    }
  private:
    std::pmr::memory_resource* resource_{};
};

